import {buildWorld,inside} from './world.js';
import * as T from './vendor/three.module.js';
const $=id=>document.getElementById(id);
const canvas=$('world'), keys=new Set();
let mode='aerial',yaw=Math.PI,pitch=0,orbit=0.35,tilt=.85,distance=710,drag=null,last=0,travel=0;
const player=new T.Vector3(),target=new T.Vector3(0,18,-30);
const scene=new T.Scene();scene.background=new T.Color('#b8c5c6');scene.fog=new T.Fog('#b8c5c6',850,1900);
const camera=new T.PerspectiveCamera(52,innerWidth/innerHeight,.1,2500);
let renderer;
try{renderer=new T.WebGLRenderer({canvas,antialias:true});}catch(e){import('./fallback.js');throw e;}
renderer.setSize(innerWidth,innerHeight);renderer.setPixelRatio(Math.min(devicePixelRatio,1.8));renderer.shadowMap.enabled=true;renderer.shadowMap.type=T.PCFSoftShadowMap;renderer.outputColorSpace=T.SRGBColorSpace;renderer.toneMapping=T.ACESFilmicToneMapping;renderer.toneMappingExposure=1.05;
scene.add(new T.HemisphereLight(0xe5f5ff,0x59614b,1.8));
const sun=new T.DirectionalLight(0xffedcf,2.5);sun.position.set(-230,440,150);sun.castShadow=true;sun.shadow.mapSize.set(2048,2048);Object.assign(sun.shadow.camera,{left:-470,right:470,top:470,bottom:-470,near:1,far:1000});sun.shadow.bias=-.0004;scene.add(sun);
let buildings=[],roads=[],places=[],labels=[],ponds=[],boundary,spawn,world;
function label(text,p,height){
 const c=document.createElement('canvas');c.width=512;c.height=96;
 const ctx=c.getContext('2d');ctx.fillStyle='#f7f7ed';ctx.beginPath();ctx.roundRect(8,8,496,74,12);ctx.fill();ctx.fillStyle='#244e40';ctx.font='600 25px Arial';ctx.textAlign='center';ctx.fillText(text,256,55);
 const sprite=new T.Sprite(new T.SpriteMaterial({map:new T.CanvasTexture(c),depthTest:true,transparent:true}));
 sprite.position.set(p[0],height+6,p[1]);const width=Math.max(19,Math.min(30,12+text.length*.55));sprite.scale.set(width,width*96/512,1);scene.add(sprite);labels.push(sprite);
}

const blocked=(x,z)=>world.blocked(x,z);
try{
const [data,config,heights]=await Promise.all(['campus.json','model-config.json','heights.json'].map(async path=>{const r=await fetch(path);if(!r.ok)throw Error(path+' unavailable');return r.json()}));
config.heights={...config.heights,...heights};world=buildWorld(scene,data,config);({buildings,roads,places,ponds,boundary,spawn}=world);
for(const p of places)label(p.shortName||p.name,p.label,p.height);
for(let i=0;i<places.length;i++){let o=document.createElement('option');o.value=i;o.textContent=places[i].name;$('destination').append(o);}
player.set(spawn[0],world.walkHeight(...spawn)+1.7,spawn[1]);$('loading').remove();requestAnimationFrame(frame);
}catch(e){$('loading').textContent='Unable to load the campus. '+e.message;console.error(e);}
function setMode(m){mode=m;document.activeElement?.blur();keys.clear();document.body.classList.toggle('walk',m==='walk');$('overview').classList.toggle('active',m==='aerial');$('walk').classList.toggle('active',m==='walk');$('walking').hidden=m!=='walk';$('crosshair').hidden=m!=='walk';if(m==='aerial')document.exitPointerLock?.();}
async function capture(){if(mode!=='walk')return;try{await canvas.requestPointerLock?.();}catch{ /* Drag-to-look remains available in embedded previews. */ }}
$('start').onclick=()=>{player.set(spawn[0],world.walkHeight(...spawn)+1.7,spawn[1]);yaw=Math.PI;pitch=0;setMode('walk');capture()};$('walk').onclick=()=>{setMode('walk');capture()};$('overview').onclick=()=>setMode('aerial');$('reset').onclick=()=>{player.set(spawn[0],world.walkHeight(...spawn)+1.7,spawn[1]);yaw=Math.PI;pitch=0;distance=710;orbit=.35;tilt=.85;travel=0};$('about').onclick=()=>{$('info').showModal();document.exitPointerLock?.();keys.clear()};$('closeInfo').onclick=()=>$('info').close();$('destination').onchange=e=>{if(e.target.value==='')return;const p=places[+e.target.value];e.target.blur();player.set(p.p[0],world.walkHeight(...p.p)+1.7,p.p[1]);setMode('walk');pitch=0;if(p.name==='Library fountain & garden'){const c=world.garden.libraryCenter;yaw=Math.atan2(player.x-c[0],player.z-c[1]);}e.target.value='';};
window.addEventListener('keydown',e=>{if(['SELECT','INPUT'].includes(e.target.tagName)||$('info').open)return;if(['ArrowUp','ArrowDown','ArrowLeft','ArrowRight','Space'].includes(e.code))e.preventDefault();keys.add(e.code);if(e.code==='KeyV'&&!e.repeat)setMode(mode==='walk'?'aerial':'walk');if(e.code==='Enter'){setMode('walk');capture()}});window.addEventListener('keyup',e=>keys.delete(e.code));window.addEventListener('blur',()=>keys.clear());document.addEventListener('visibilitychange',()=>keys.clear());
canvas.addEventListener('pointerdown',e=>{drag=[e.clientX,e.clientY];canvas.setPointerCapture(e.pointerId);if(mode==='walk'&&e.pointerType==='mouse')capture()});canvas.addEventListener('pointerup',()=>drag=null);canvas.addEventListener('pointercancel',()=>drag=null);
function look(dx,dy){yaw-=dx*.003;pitch=Math.max(-1.35,Math.min(1.35,pitch-dy*.003));}
window.addEventListener('pointermove',e=>{if(document.pointerLockElement===canvas&&mode==='walk')look(e.movementX,e.movementY);else if(drag){const dx=e.clientX-drag[0],dy=e.clientY-drag[1];drag=[e.clientX,e.clientY];if(mode==='walk')look(dx,dy);else{orbit-=dx*.005;tilt=Math.max(.25,Math.min(1.48,tilt+dy*.004))}}});
canvas.addEventListener('wheel',e=>{if(mode==='aerial'){e.preventDefault();distance=Math.max(180,Math.min(1150,distance+e.deltaY*.5))}},{passive:false});
for(const b of document.querySelectorAll('[data-key]')){b.onpointerdown=e=>{e.preventDefault();b.setPointerCapture(e.pointerId);keys.add(b.dataset.key)};b.onpointerup=b.onpointercancel=()=>keys.delete(b.dataset.key);}
window.addEventListener('resize',()=>{camera.aspect=innerWidth/innerHeight;camera.updateProjectionMatrix();renderer.setSize(innerWidth,innerHeight)});
const ctx=$('map').getContext('2d');let mapFrame=0;
function map(){ctx.clearRect(0,0,260,310);const mx=x=>130+x*.39,mz=z=>155+z*.39;function path(p){ctx.beginPath();p.forEach((v,i)=>i?ctx.lineTo(mx(v[0]),mz(v[1])):ctx.moveTo(mx(v[0]),mz(v[1])))}path(boundary);ctx.fillStyle='#dde6ca';ctx.fill();ctx.strokeStyle='#afc4a5';ctx.lineWidth=1;ctx.stroke();ctx.strokeStyle='#343738';for(const r of roads){path([r.a,r.b]);ctx.lineWidth=r.width*.39;ctx.stroke()}for(const b of buildings){path(b.points);ctx.fillStyle='#985344';ctx.fill()}for(const p of ponds){path(p.points);ctx.fillStyle='#587b59';ctx.fill()}if(world.garden){const g=world.garden;path(Array.from({length:49},(_,i)=>g.point(Math.cos(i*Math.PI/24)*g.halfWidth,Math.sin(i*Math.PI/24)*g.halfLength)));ctx.fillStyle='#6c934a';ctx.fill();ctx.beginPath();ctx.arc(mx(g.fountain[0]),mz(g.fountain[1]),g.basinRadius*.39,0,Math.PI*2);ctx.fillStyle='#409aa6';ctx.fill()}if(mode==='walk'){const x=mx(player.x),y=mz(player.z);ctx.save();ctx.translate(x,y);ctx.rotate(-yaw);ctx.beginPath();ctx.moveTo(0,-11);ctx.lineTo(-6,6);ctx.lineTo(6,6);ctx.closePath();ctx.fillStyle='#ec804a';ctx.strokeStyle='white';ctx.lineWidth=2;ctx.fill();ctx.stroke();ctx.restore();}ctx.fillStyle='#536b5b';ctx.font='10px Arial';ctx.fillText('100 m',10,300);ctx.fillRect(10,285,39,2);}
function frame(time){let dt=Math.min((time-last)/1000||.016,.05);last=time;if(mode==='walk'&&!$('info').open){let f=(keys.has('KeyW')||keys.has('ArrowUp')?1:0)-(keys.has('KeyS')||keys.has('ArrowDown')?1:0),s=(keys.has('KeyD')||keys.has('ArrowRight')?1:0)-(keys.has('KeyA')||keys.has('ArrowLeft')?1:0),speed=(keys.has('ShiftLeft')||keys.has('ShiftRight')?11:4.8)*dt/Math.max(1,Math.hypot(f,s));let dx=(-Math.sin(yaw)*f+Math.cos(yaw)*s)*speed,dz=(-Math.cos(yaw)*f-Math.sin(yaw)*s)*speed;const steps=Math.max(1,Math.ceil(Math.hypot(dx,dz)/.25));for(let i=0;i<steps;i++){if(!blocked(player.x+dx/steps,player.z)&&inside(player.x+dx/steps,player.z,boundary))player.x+=dx/steps;if(!blocked(player.x,player.z+dz/steps)&&inside(player.x,player.z+dz/steps,boundary))player.z+=dz/steps;}travel+=Math.hypot(dx,dz);player.y=world.walkHeight(player.x,player.z)+1.7;camera.position.copy(player);camera.rotation.order='YXZ';camera.rotation.set(pitch,yaw,0);const near=places.reduce((a,b)=>Math.hypot(player.x-b.p[0],player.z-b.p[1])<Math.hypot(player.x-a.p[0],player.z-a.p[1])?b:a,places[0]);$('location').textContent='Near '+near.name;$('walkStatus').textContent='Walking · '+near.name;}else if(mode==='aerial'){camera.position.set(target.x+Math.sin(orbit)*Math.cos(tilt)*distance,target.y+Math.sin(tilt)*distance,target.z+Math.cos(orbit)*Math.cos(tilt)*distance);camera.lookAt(target);$('location').textContent='Aerial overview';}labels.forEach(l=>{l.visible=mode==='aerial'||l.position.distanceTo(player)<110});if(++mapFrame%4===0)map();renderer.render(scene,camera);requestAnimationFrame(frame);}
